-- Window and workspace rules

-- Float specific windows
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.window_rule({
    name = "windowrule-1",
    match = {
        class = "^(pavucontrol)$",
    },
    float = true,
})

hl.window_rule({
    name = "windowrule-2",
    match = {
        class = "^(blueman-manager)$",
    },
    float = true,
})

hl.window_rule({
    name = "windowrule-3",
    match = {
        class = "^(nm-connection-editor)$",
    },
    float = true,
})

hl.window_rule({
    name = "windowrule-4",
    match = {
        title = "^(Picture-in-Picture)$",
    },
    float = true,
})

hl.window_rule({
    name = "windowrule-5",
    match = {
        class = "^(xdg-desktop-portal-gtk)$",
    },
    float = true,
})

-- Dialogs should float 1
hl.window_rule({
    name = "windowrule-6",
    match = {
        title = "^(Open File)$",
    },
    float = true,
})

hl.window_rule({
    name = "windowrule-7",
    match = {
        title = "^(Save File)$",
    },
    float = true,
})

hl.window_rule({
    name = "windowrule-8",
    match = {
        title = "^(Select a File)$",
    },
    float = true,
})

hl.window_rule({
    name = "windowrule-9",
    match = {
        class = "^(.*)",
        title = "^(.*Authentication Required.*)$",
    },
    float = true,
})

-- Center float 1ing windows
hl.window_rule({
    name = "windowrule-10",
    center = true,
    -- TODO: manual review — unmapped window rule action: "float 1ing:1"
})

